def intake(con, payload):
    required = {
        "call_id", "request_key", "buyer_id", "gross_cents",
        "supplier_cents", "evidence_hash", "expires_at",
        "permission_verified", "suppression_clear",
    }
    if set(payload) != required:
        raise ValueError("Intake fields must match the declared contract")
    for field in ("call_id", "request_key", "buyer_id"):
        if not isinstance(payload[field], str) or not payload[field]:
            raise ValueError("Identifiers must be nonempty strings")
    for field in ("gross_cents", "supplier_cents", "expires_at"):
        if type(payload[field]) is not int:
            raise ValueError("Amounts and expiry require integer values")
    require_hash(payload["evidence_hash"])
    fingerprint = digest(payload)
    with transaction(con):
        old = con.execute(
            "SELECT * FROM calls WHERE request_key = ?",
            (payload["request_key"],),
        ).fetchone()
        if old:
            if old["payload_hash"] != fingerprint:
                raise ValueError("Request key conflicts with prior intake")
            return old["call_id"]
        if payload["permission_verified"] is not True:
            raise ValueError("Validated permission evidence is required")
        if payload["suppression_clear"] is not True:
            raise ValueError("Applicable suppression checks must pass")
        if payload["expires_at"] <= int(time.time()):
            raise ValueError("Quote or evidence validity has expired")
        gross = payload["gross_cents"]
        supplier = payload["supplier_cents"]
        if gross <= 0 or not 0 <= supplier <= gross:
            raise ValueError("Invalid call economics")
        if supplier * 100 > gross * 45:
            raise ValueError("Acquisition exceeds this route's 45 percent cap")
        con.execute(
            """INSERT INTO calls (
                call_id, request_key, payload_hash, buyer_id,
                gross_cents, supplier_cents, evidence_hash,
                expires_at, state
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'QUALIFIED')""",
            (
                payload["call_id"], payload["request_key"], fingerprint,
                payload["buyer_id"], gross, supplier,
                payload["evidence_hash"], payload["expires_at"],
            ),
        )
        return payload["call_id"]

ALLOWED = {
    "QUALIFIED": {"RESERVED", "REJECTED"},
    "RESERVED": {"CONNECTED", "REJECTED"},
    "CONNECTED": {"VERIFIED", "REJECTED"},
    "VERIFIED": {"REJECTED"},
}

def move(con, call_id, target, event_key, proof_hash):
    require_hash(proof_hash)
    payload = {"target": target, "proof_hash": proof_hash}
    with transaction(con):
        if not fresh_event(con, event_key, call_id, payload):
            return False
        call = con.execute(
            "SELECT * FROM calls WHERE call_id = ?", (call_id,)
        ).fetchone()
        if target not in ALLOWED.get(call["state"], set()):
            raise ValueError("Transition conflicts with current call state")
        if target == "RESERVED":
            if call["expires_at"] <= int(time.time()):
                raise ValueError("Expired intake cannot reserve capacity")
            updated = con.execute(
                """UPDATE buyers SET held_cents = held_cents + ?
                   WHERE buyer_id = ?
                   AND held_cents + ? <= cap_cents""",
                (call["gross_cents"], call["buyer_id"], call["gross_cents"]),
            ).rowcount
            if updated != 1:
                raise ValueError("Buyer exposure limit reached")
            con.execute(
                "INSERT INTO dispatch(dispatch_key, call_id) VALUES (?, ?)",
                ("route/" + call["request_key"], call_id),
            )
        if target == "REJECTED" and call["state"] != "QUALIFIED":
            con.execute(
                "UPDATE buyers SET held_cents = held_cents - ? WHERE buyer_id = ?",
                (call["gross_cents"], call["buyer_id"]),
            )
        con.execute(
            "UPDATE calls SET state = ? WHERE call_id = ?",
            (target, call_id),
        )
        return True

def dispatch_pending(con, send_idempotently):
    rows = con.execute(
        """SELECT d.dispatch_key, d.call_id
           FROM dispatch d JOIN calls c ON c.call_id = d.call_id
           WHERE d.receipt IS NULL AND c.state = 'RESERVED'
           ORDER BY d.dispatch_key"""
    ).fetchall()
    for row in rows:
        # The adapter must atomically validate current eligibility and
        # deduplicate this key at its delivery boundary.
        receipt = send_idempotently(row["dispatch_key"], row["call_id"])
        if not isinstance(receipt, str) or not receipt:
            raise ValueError("Delivery adapter must return a durable receipt")
        with transaction(con):
            old = con.execute(
                "SELECT receipt FROM dispatch WHERE dispatch_key = ?",
                (row["dispatch_key"],),
            ).fetchone()["receipt"]
            if old is not None and old != receipt:
                raise ValueError("Delivery key returned conflicting receipts")
            con.execute(
                "UPDATE dispatch SET receipt = ? WHERE dispatch_key = ?",
                (receipt, row["dispatch_key"]),
            )

def balanced_entries(con, event_key, lines):
    if sum(debit for _, debit, _ in lines) != sum(
        credit for _, _, credit in lines
    ):
        raise ValueError("Journal event must balance")
    for account, debit, credit in lines:
        if debit or credit:
            con.execute(
                """INSERT INTO journal (
                    event_key, account, debit_cents, credit_cents
                ) VALUES (?, ?, ?, ?)""",
                (event_key, account, debit, credit),
            )

def money(con, call_id, action, proof_hash):
    require_hash(proof_hash)
    if action not in {"invoice", "collect", "pay_supplier"}:
        raise ValueError("Unsupported accounting action")
    event_key = "money/" + call_id + "/" + action
    with transaction(con):
        if not fresh_event(
            con, event_key, call_id,
            {"action": action, "proof_hash": proof_hash},
        ):
            return False
        call = con.execute(
            "SELECT * FROM calls WHERE call_id = ?", (call_id,)
        ).fetchone()
        gross = call["gross_cents"]
        supplier = call["supplier_cents"]
        if action == "invoice":
            if call["state"] != "VERIFIED":
                raise ValueError("Only finally verified calls can be invoiced")
            lines = [
                ("buyer_receivable", gross, 0),
                ("supplier_payable", 0, supplier),
                ("retained_revenue", 0, gross - supplier),
            ]
            con.execute(
                "UPDATE calls SET state = 'SETTLED' WHERE call_id = ?",
                (call_id,),
            )
        elif action == "collect":
            if call["state"] != "SETTLED":
                raise ValueError("Collection requires an open final invoice")
            lines = [("cash", gross, 0), ("buyer_receivable", 0, gross)]
            con.execute(
                "UPDATE calls SET state = 'PAID' WHERE call_id = ?",
                (call_id,),
            )
            con.execute(
                "UPDATE buyers SET held_cents = held_cents - ? WHERE buyer_id = ?",
                (gross, call["buyer_id"]),
            )
        else:
            if call["state"] not in {"SETTLED", "PAID"}:
                raise ValueError("Supplier payment requires a final invoice")
            if call["supplier_paid"]:
                raise ValueError("Supplier obligation was already paid")
            lines = [("supplier_payable", supplier, 0), ("cash", 0, supplier)]
            con.execute(
                "UPDATE calls SET supplier_paid = 1 WHERE call_id = ?",
                (call_id,),
            )
        balanced_entries(con, event_key, lines)
        return True
